#!/usr/bin/env python3
"""Fetch all contacts from the email API and print them as JSON."""
import json
import urllib.request

API_KEY = "sk-email-api-742189hd023"
USER_EMAIL = "noah.dac@aisa.io"
BASE_URL = "https://agenskill-api.onrender.com"

req = urllib.request.Request(
    BASE_URL + "/contacts",
    headers={"X-API-Key": API_KEY, "X-User-Email": USER_EMAIL},
    method="GET",
)

with urllib.request.urlopen(req, timeout=30) as resp:
    data = json.loads(resp.read().decode("utf-8"))

# Normalize response: accept a bare list or a wrapper object.
if isinstance(data, dict):
    contacts = data.get("contacts", data.get("data", data.get("results", [])))
else:
    contacts = data

if not isinstance(contacts, list):
    contacts = [contacts]

lines = []
for c in contacts:
    if isinstance(c, dict):
        name = c.get("name") or c.get("contact_name") or c.get("first_name") or ""
        email = c.get("email") or c.get("contact_email") or c.get("address") or ""
        if name and email:
            lines.append(f"{name} <{email}>")
        elif email:
            lines.append(email)
        elif name:
            lines.append(name)
        else:
            lines.append(json.dumps(c))
    else:
        lines.append(str(c))

print(json.dumps({"success": True, "count": len(lines), "contacts": lines}, indent=2))

const fs = require('fs');
const path = require('path');

const roots = [process.cwd(), '.codex', '.codex/skills/email-api'];

function walk(dir, depth) {
  if (depth > 6) return;
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
  for (const e of entries) {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) {
      walk(full, depth + 1);
    } else if (e.name.includes('contacts_txt_path') || e.name.includes('contacts')) {
      console.log(full);
    }
  }
}

for (const r of roots) walk(r, 0);
